import type { Context } from 'hono';
import type { AppEnvironment } from '@/app';
import {
    SITE_PACKAGE_ARCHIVE_LIMITS,
    type SitePackageArchiveManifest,
    type SitePackageRuntimeMode
} from '@/domains/site-packages/package-archive';
import {
    oneArchiveFile,
    parseUploadedSitePackage,
    sitePackageDescription,
    sitePackageRuntimeMode,
    sitePackageSlug,
    sitePackageTitle,
    sitePackageUuid
} from '@/domains/site-packages/site-package-support';
import { services } from '@/middleware/hono-context';
import type { UploadedFile } from '@/ports/http';
import { requestRecord } from '@/utils/validation/request-data';

const PREVIEW_TOKEN_PATTERN = /^[a-f0-9]{64}$/i;

export interface SitePackageIdParams {
    id: string;
}

export interface SitePackageRevisionParams extends SitePackageIdParams {
    revisionId: string;
}

export interface PublicSitePackageParams {
    slug: string | null;
}

export interface PublishedSitePackageParams extends PublicSitePackageParams {
    revisionId: string | null;
}

export interface PreviewSitePackageParams {
    previewToken: string | null;
}

interface ParsedSitePackageUploadRequest {
    archive: UploadedFile;
    manifest: SitePackageArchiveManifest;
    runtimeMode: SitePackageRuntimeMode;
}

export interface CreateSitePackageRequest extends ParsedSitePackageUploadRequest {
    slug: string;
    title: string;
    description: string;
}

export type CreateSitePackageRevisionRequest = ParsedSitePackageUploadRequest;

interface RawSitePackageUploadRequest {
    archive: UploadedFile;
    fields: { [field: string]: string };
    maxArchiveBytes: number;
}

function paramValue(value: unknown, field: string): unknown {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
    return (value as { [key: string]: unknown })[field];
}

function publicSlug(value: unknown): string | null {
    try {
        return sitePackageSlug(value);
    } catch {
        return null;
    }
}

function publicRevisionId(value: unknown): string | null {
    try {
        return sitePackageUuid(value, '版本 ID');
    } catch {
        return null;
    }
}

export function validateSitePackageIdParams(value: unknown): SitePackageIdParams {
    const params = requestRecord(value, '站点包 ID无效');
    return { id: sitePackageUuid(params.id, '站点包 ID') };
}

export function validateSitePackageRevisionParams(value: unknown): SitePackageRevisionParams {
    const params = requestRecord(value, '站点包版本参数无效');
    return {
        id: sitePackageUuid(params.id, '站点包 ID'),
        revisionId: sitePackageUuid(params.revisionId, '版本 ID')
    };
}

export function validatePublicSitePackageParams(value: unknown): PublicSitePackageParams {
    return { slug: publicSlug(paramValue(value, 'slug')) };
}

export function validatePublishedSitePackageParams(value: unknown): PublishedSitePackageParams {
    return {
        slug: publicSlug(paramValue(value, 'slug')),
        revisionId: publicRevisionId(paramValue(value, 'revisionId'))
    };
}

export function validatePreviewSitePackageParams(value: unknown): PreviewSitePackageParams {
    const candidate = paramValue(value, 'previewToken');
    const previewToken = typeof candidate === 'string' && PREVIEW_TOKEN_PATTERN.test(candidate)
        ? candidate
        : null;
    return { previewToken };
}

async function parseSitePackageUploadRequest(
    c: Context<AppEnvironment>
): Promise<RawSitePackageUploadRequest> {
    const runtime = services(c);
    if (!runtime.uploads || !runtime.storage) throw new Error('Site-package upload unavailable');
    const maxArchiveBytes = Math.min(
        runtime.config?.sitePackageMaxUploadBytes || SITE_PACKAGE_ARCHIVE_LIMITS.archiveBytes,
        SITE_PACKAGE_ARCHIVE_LIMITS.archiveBytes
    );
    const upload = await runtime.uploads.parse(c.req.raw, {
        maxBytes: maxArchiveBytes + 64 * 1024,
        fileFields: ['archive'],
        maxFiles: 1,
        maxFields: 5,
        maxParts: 7
    });
    const archive = oneArchiveFile(upload.files.archive);
    return { archive, fields: upload.fields, maxArchiveBytes };
}

async function parseArchiveRequest(
    upload: RawSitePackageUploadRequest,
    runtimeMode: SitePackageRuntimeMode
): Promise<ParsedSitePackageUploadRequest> {
    if (upload.archive.body.byteLength > upload.maxArchiveBytes) {
        throw Object.assign(new Error('站点包超过配置的上传限制'), { status: 413 });
    }
    const manifest = await parseUploadedSitePackage(
        upload.archive,
        upload.fields.entryPath || 'index.html',
        runtimeMode
    );
    return { archive: upload.archive, manifest, runtimeMode };
}

export async function parseCreateSitePackageRequest(
    c: Context<AppEnvironment>
): Promise<CreateSitePackageRequest> {
    const upload = await parseSitePackageUploadRequest(c);
    const slug = sitePackageSlug(upload.fields.slug);
    const title = sitePackageTitle(upload.fields.title);
    const description = sitePackageDescription(upload.fields.description);
    const runtimeMode = sitePackageRuntimeMode(upload.fields.runtimeMode);
    const parsed = await parseArchiveRequest(upload, runtimeMode);
    return {
        archive: parsed.archive,
        manifest: parsed.manifest,
        runtimeMode: parsed.runtimeMode,
        slug,
        title,
        description
    };
}

export async function parseCreateSitePackageRevisionRequest(
    c: Context<AppEnvironment>
): Promise<CreateSitePackageRevisionRequest> {
    const upload = await parseSitePackageUploadRequest(c);
    const runtimeMode = sitePackageRuntimeMode(upload.fields.runtimeMode);
    return parseArchiveRequest(upload, runtimeMode);
}
